{"operationName":"suggestQuery","variables":{"productsSize":0,"skipProducts":false,"query":"TheMarkup","termsSize":10},"query":"query suggestQuery($query: String!, $termsSize: Int, $productsSize: Int = 0, $categoriesSize: Int, $brandsSize: Int, $partnerId: String, $skipProducts: Boolean = false) {
  suggest(
    suggestRequest: {query: $query, termsSize: $termsSize, productsSize: $productsSize, categoriesSize: $categoriesSize, brandsSize: $brandsSize, metadata: {partnerId: $partnerId}}
  ) {
    terms {
      term
      count
      __typename
    }
    products @skip(if: $skipProducts) {
      id
      variationId
      title
      price {
        realPrice: price
        __typename
      }
      path
      image
      __typename
    }
    __typename
  }
}
"}
